    expect(
      maybeTrimSentenceCount(
        "The job's `headSha` ('a'.repeat(40)) differs from v1.2 here. Second. Third.",
        2,
      ),
    ).toBe(
      "The job's `headSha` ('a'.repeat(40)) differs from v1.2 here. Second.",
    );
  });

